node -e "
const fs = require('fs');
const zlib = require('zlib');

// Minimal ZIP parser to extract word/document.xml
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Find local file headers (PK\x03\x04)
let offset = 0;
while (offset < buf.length - 4) {
    if (buf[offset] === 0x50 && buf[offset+1] === 0x4B && buf[offset+2] === 0x03 && buf[offset+3] === 0x04) {
        const compressionMethod = buf.readUInt16LE(offset + 8);
        const compressedSize = buf.readUInt32LE(offset + 18);
        const uncompressedSize = buf.readUInt32LE(offset + 22);
        const fileNameLen = buf.readUInt16LE(offset + 26);
        const extraLen = buf.readUInt16LE(offset + 28);
        const fileName = buf.slice(offset + 30, offset + 30 + fileNameLen).toString('utf8');
        const dataStart = offset + 30 + fileNameLen + extraLen;

        if (fileName === 'word/document.xml') {
            let content;
            if (compressionMethod === 0) {
                content = buf.slice(dataStart, dataStart + compressedSize).toString('utf8');
            } else {
                content = zlib.inflateRawSync(buf.slice(dataStart, dataStart + compressedSize)).toString('utf8');
            }
            // Extract text between <w:t> tags, preserving paragraph breaks
            // First split by paragraph
            const paragraphs = content.split(/<\/w:p>/);
            const lines = paragraphs.map(p => {
                const texts = [];
                const re = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;
                let m;
                while ((m = re.exec(p)) !== null) {
                    texts.push(m[1]);
                }
                return texts.join('');
            }).filter((line, i, arr) => i < arr.length); // keep all including empty
            console.log(lines.join('\n'));
            break;
        }
        offset = dataStart + compressedSize;
    } else {
        offset++;
    }
}
"
